tion:width .6s}.stat-value{text-align:right;font-size:10px;font-weight:700;color:#3e4c54}.panel-rule{height:1px;background:#e9e8e2;margin:13px 0 16px}.decision-heading{align-items:flex-end}.decision-heading h2{font-size:18px}.ap-chip{font-size:8px;letter-spacing:.7px;color:#84714e;background:#f4f0e5;padding:5px 7px;border-radius:2px}.ap-chip b{font-size:11px;margin-right:2px}.decision-intro{font-size:10px;line-height:1.5;color:#818991;margin:8px 0 11px}.decision-list{display:flex;flex-direction:column;gap:8px}.decision-card{border:1px solid #e8e7e1;background:#fff;text-align:left;padding:11px 12px;cursor:pointer;transition:.18s;border-radius:2px;color:#34414b;width:100%}.decision-card:hover{border-color:#b9a16f;background:#fbfaf6;transform:translateY(-1px)}.decision-card:disabled{opacity:.42;cursor:not-allowed;transform:none}.decision-card-top{display:flex;justify-content:space-between;gap:8px;align-items:center}.decision-card h3{margin:0;font:600 12px var(--serif)}.decision-cost{font-size:8px;letter-spacing:.8px;color:#a28453;white-space:nowrap}.decision-card p{margin:5px 0 0;color:#838b91;font-size:9px;line-height:1.45}.cabinet-note{margin-top:14px;background:#f4f2eb;padding:11px;display:flex;gap:9px;border-left:2px solid #c0a36d}.note-icon{font-size:13px;color:#a98c5c}.cabinet-note b{font-size:9px;color:#56626a}.cabinet-note p{font:italic 10px/1.45 var(--serif);color:#727a7c;margin:4px 0 0}.end-turn-button{display:flex;justify-content:space-between;align-items:center;width:100%;padding:11px 13px;margin-top:12px;border:0;background:#1a2938;color:white;font:600 10px var(--sans);cursor:pointer;letter-spacing:.4px}.end-turn-button:hover{background:#26394b}.end-turn-button b{font-size:16px;color:#d0b47d}.fine-print{text-align:center;color:#a2a5a4;font-size:8px;margin:10px 0}.toast{position:fixed;bottom:28px;left:50%;transform:translate(-50%,20px);padding:11px 17px;background:#192838;color:#fff;border:1px solid #a78c5b;border-radius:3px;box-shadow:0 8px 30px #0003;font-size:11px;z-index:15;opacity:0;pointer-events:none;transition:.25s}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-backdrop{position:fixed;inset:0;background:#101a27a8;z-index:20;display:grid;place-items:center;padding:18px;backdrop-filter:blur(4px)}.modal-backdrop.hidden{display:none}.modal{width:min(520px,100%);max-height:85vh;overflow:auto;background:#faf9f5;padding:26px 28px 24px;box-shadow:0 20px 70px #0005;border-top:3px solid #b89a63;position:relative}.modal-close{position:absolute;right:16px;top:14px;border:0;background:none;font-size:22px;color:#7e8589;cursor:pointer}.modal .eyebrow{color:#9a8358}.modal h2{font:600 26px var(--serif);margin:6px 25px 8px 0;color:#23313b}.modal p{font-size:12px;line-height:1.7;color:#69747a}.modal-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:19px}.modal-actions button,.primary-button{background:#1b2b3a;color:white;border:0;padding:11px 15px;font:600 10px var(--sans);cursor:pointer}.modal-actions button.secondary{background:transparent;color:#52606a;border:1px solid #d7d6cf}.log-list{margin-top:18px;display:flex;flex-direction:column;gap:9px}.log-entry{border-left:2px solid #c1a470;padding:7px 10px;background:#f2f1eb}.log-entry b{font-size:9px;letter-spacing:.6px;color:#8c754b}.log-entry p{margin:4px 0 0;font-size:10px}.agenda-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:16px}.agenda-cell{background:#f0efe9;padding:12px}.agenda-cell span{font-size:8px;color:#987f52;letter-spacing:1px}.agenda-cell b{display:block;font:600 13px var(--serif);margin-top:5px}.stats-explain{margin-top:15px;padding:12px;background:#f2f1eb;font-size:10px;line-height:1.6;color:#68747a}
