  $('chart-line').setAttribute('d',`M${points}`); $('chart-area').setAttribute('d',`M${points} L120,44 L0,44 Z`);
  $('approval-change').textContent=`${game.change>=0?'+':''}${game.change||0} THIS WEEK`;
