35: function loadGame(){ try { const s=JSON.parse(localStorage.getItem('theOvalSave')); return s && s.week ? {...initial,...s} : {...initial}; } catch { return {...initial}; } }
36: const statMeta = [ ['economy','Economy'], ['unity','National unity'], ['stability','Security'], ['climate','Climate'] ];
37: function clamp(n){ return Math.max(0,Math.min(100,Math.round(n))); }
38: function save(){ localStorage.setItem('theOvalSave',JSON.stringify(game)); }
