41: function render(){
42:   const room=rooms[game.room]||rooms.office;
43:   $('date-label').textContent = `JAN ${20 + ((game.week-1)*7)%31} · YEAR ${Math.floor((game.week-1)/52)+1}`;
44:   $('term-label').textContent = game.week>208?'SECOND TERM':'FIRST TERM';
45:   $('week-number').textContent=String(game.week).padStart(2,'0');
46:   $('action-label').textContent=game.actions; $('ap-chip').textContent=game.actions;
