48:   $('room-title').textContent=room.title; $('room-kicker').textContent=room.kicker; $('room-subtitle').textContent=room.subtitle; $('scene-location').textContent=room.location;
49:   $('decision-room-title').textContent=game.room==='office'?'Decisions':game.room==='war'?'Security options':'Public engagement';
50:   $('decision-intro').textContent=room.intro; $('advisor-note').textContent=room.note;
