54:   const ds=decisionSet[game.room];
55:   $('decision-list').innerHTML=ds.map((d,i)=>`<button class="decision-card" data-decision="${i}" ${game.actions<1||game.finished?'disabled':''}><div class="decision-card-top"><h3>${d.title}</h3><span class="decision-cost">1 AP</span></div><p>${d.desc}</p></button>`).join('');
56:   document.querySelectorAll('.decision-card').forEach(b=>b.addEventListener('click',()=>makeDecision(Number(b.dataset.decision))));
57:   const vals=game.history.slice(-8), min=Math.min(...vals)-2, max=Math.max(...vals)+2;
