60:   $('approval-change').textContent=`${game.change>=0?'+':''}${game.change||0} THIS WEEK`;
61:   $('next-week').disabled=game.finished; $('end-turn-button').disabled=game.finished;
62: }
63: function makeDecision(index){
64:   if(game.actions<1||game.finished)return;
65:   const d=decisionSet[game.room][index]; if(!d)return;
66:   Object.entries(d.effects).forEach(([key,amount])=>{if(key in game)game[key]=clamp(game[key]+amount);});
67:   game.actions--; game.headline=d.message;
68:   game.log.unshift({week:game.week,room:rooms[game.room].title,title:d.title,text:d.message}); game.change=Object.values(d.effects).reduce((a,b)=>a+b,0);
69:   save();render();toast(`Decision recorded · ${game.actions} ${game.actions===1?'decision':'decisions'} remaining`);
70: }
71: function advanceWeek(){
72:   if(game.finished)return;
73:   game.week++; game.actions=2;
74:   const drift=(key,amount)=>game[key]=clamp(game[key]+amount);
75:   // Public mood shifts gently with the underlying state; good governance is cumulative.
76:   const mood=Math.round((game.economy+game.unity+game.stability+game.climate)/4);
77:   let delta=mood>60?1:mood<38?-2:0;
78:   drift('approval',delta); game.change=delta;
79:   if(game.week%4===0){
80:     const events=[
81:       {headline:'A major storm makes landfall. Emergency teams are mobilized across the coast.',effects:{stability:-2,economy:-1}},
