83:       {headline:'A diplomatic breakthrough offers a chance to cool a regional dispute.',effects:{stability:2,unity:1}},
84:       {headline:'Public attention turns to the rising cost of everyday essentials.',effects:{economy:-2,approval:-1}},
85:       {headline:'A bipartisan group of governors announces a shared climate initiative.',effects:{climate:2,unity:1}},
86:       {headline:'An independent watchdog calls for greater transparency in government.',effects:{unity:-1,approval:-1}}
87:     ];
88:     const event=events[Math.floor(Math.random()*events.length)]; game.headline=event.headline;
89:     Object.entries(event.effects).forEach(([k,v])=>drift(k,v));
90:     game.log.unshift({week:game.week,room:'The country',title:'A week in the news',text:event.headline});
91:   }else game.headline=delta>0?'Steady progress lifts the national mood. The work continues.':delta<0?'A difficult week tests the country’s patience. The work continues.':'The country takes stock. Your next choices will shape the week ahead.';
92:   game.history.push(game.approval); game.history=game.history.slice(-8);
93:   if(game.week>208){game.finished=true;showFinal();}
94:   save();render();toast('A new week begins. Your cabinet is ready.');
95: }
