264: function talkToNearby(){if(!nearbyNpc){toast('Walk closer to a minister or advisor to talk.');return;}const npc=nearbyNpc;const line=npc.lines[(game.week+game.log.length)%npc.lines.length];openModal(`<button class="modal-close" aria-label="Close">×</button><div class="eyebrow">PRIVATE CONVERSATION · WEEK ${String(game.week).padStart(2,'0')}</div><h2>${npc.name}</h2><p class="conversation-role">${npc.role}</p><blockquote class="conversation-quote">“${line}”</blockquote><div class="conversation-options"><button data-reply="policy">Discuss the weekly agenda</button><button class="secondary" data-reply="listen">Ask for their recommendation</button></div><div class="modal-actions"><button class="modal-close">End conversation</button></div>`);$('modal').querySelectorAll('[data-reply]').forEach(button=>button.addEventListener('click',()=>{const reply=button.dataset.reply==='policy'?'You share your priorities. Your advisor will prepare options for the next briefing.':'You ask for a candid recommendation. The conversation is added to your presidential record.';if(button.dataset.reply==='listen'){game.log.unshift({week:game.week,room:rooms[game.room].title,title:`Conversation with ${npc.name}`,text:line});save();}toast(reply);closeModal();}));}
