import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(`${runtime}/display`, 'utf8').trim();
const browser = await chromium.launch(config.browser.launchOptions);
const results = {};
try {
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://127.0.0.1:4173', { waitUntil: 'load' });
  await page.waitForFunction(() => document.querySelector('#scene-loader')?.classList.contains('done'), { timeout: 15000 });
  results.renderer = await page.locator('#scene-container canvas').evaluate(c => c.className || 'webgl-canvas');
  await page.keyboard.down('w'); await page.waitForTimeout(800); await page.keyboard.up('w');
  await page.waitForFunction(() => document.querySelector('#interaction-prompt')?.textContent.includes('Chief of Staff') || document.querySelector('#interaction-prompt')?.textContent.includes('Secretary of State'), { timeout: 5000 });
  results.approachPrompt = await page.locator('#interaction-prompt').innerText();
  await page.keyboard.press('e');
  await page.locator('#modal').waitFor({ state: 'visible' });
  results.conversation = await page.locator('#modal h2').innerText();
  await page.locator('#modal .modal-close').first().click();
  await page.locator('.room-tab[data-room="war"]').click();
  await page.waitForFunction(() => document.querySelector('#room-title')?.textContent.includes('Situation'));
  results.situationRoom = await page.locator('#room-title').innerText();
  await page.locator('.room-tab[data-room="press"]').click();
  await page.waitForFunction(() => document.querySelector('#room-title')?.textContent.includes('Press'));
  results.pressRoom = await page.locator('#room-title').innerText();
  results.desktopErrors = errors;
  await page.close();

  const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
  await mobile.goto('http://127.0.0.1:4173', { waitUntil: 'load' });
  await mobile.waitForFunction(() => document.querySelector('#scene-loader')?.classList.contains('done'), { timeout: 15000 });
  await mobile.locator('[data-move="forward"]').dispatchEvent('pointerdown', { pointerType: 'touch' });
  await mobile.waitForTimeout(850);
  await mobile.locator('[data-move="forward"]').dispatchEvent('pointerup', { pointerType: 'touch' });
  await mobile.waitForFunction(() => document.querySelector('#interaction-prompt')?.textContent.trim(), { timeout: 5000 });
  results.mobilePrompt = (await mobile.locator('#interaction-prompt').innerText()).trim();
  await mobile.locator('#talk-button').click();
  await mobile.locator('#modal h2').waitFor({ state: 'visible' });
  results.mobileConversation = await mobile.locator('#modal h2').innerText();
  await mobile.close();

  const fallback = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  await fallback.route('https://cdn.jsdelivr.net/**', route => route.abort());
  await fallback.goto('http://127.0.0.1:4173', { waitUntil: 'load' });
  await fallback.waitForSelector('canvas.fallback-scene', { timeout: 15000 });
  results.fallback = 'illustrated canvas loaded';
  await fallback.keyboard.down('w'); await fallback.waitForTimeout(850); await fallback.keyboard.up('w');
  await fallback.waitForFunction(() => document.querySelector('#interaction-prompt')?.textContent.trim(), { timeout: 5000 });
  results.fallbackPrompt = (await fallback.locator('#interaction-prompt').innerText()).trim();
  await fallback.keyboard.press('e');
  await fallback.locator('#modal h2').waitFor({ state: 'visible' });
  results.fallbackConversation = await fallback.locator('#modal h2').innerText();
  await fallback.locator('.room-tab[data-room="war"]').click();
  await fallback.waitForFunction(() => document.querySelector('#room-title')?.textContent.includes('Situation'));
  results.fallbackRoomSwitch = await fallback.locator('#room-title').innerText();
  await fallback.close();
  if (results.desktopErrors.length) throw new Error(`Desktop page errors: ${results.desktopErrors.join('; ')}`);
  console.log(JSON.stringify(results, null, 2));
} finally { await browser.close(); }
