262: function movePlayer(dt){if($('modal-backdrop')&&!$('modal-backdrop').classList.contains('hidden'))return;let forward=moveVector.forward-moveVector.back,side=moveVector.right-moveVector.left;if(!forward&&!side)return;const mag=Math.hypot(forward,side);forward/=mag;side/=mag;const yaw=player.yaw+lookOffset,speed=3.15*dt;const dx=(Math.sin(yaw)*forward+Math.cos(yaw)*side)*speed,dz=(-Math.cos(yaw)*forward+Math.sin(yaw)*side)*speed;const nx=player.x+dx,nz=player.z+dz;if(!blocked(nx,player.z))player.x=nx;if(!blocked(player.x,nz))player.z=nz;updateCamera();if(!renderer)drawFallback(game.room);}
